const express = require('express');
const { requireToken } = require('../auth/token');
const { ClusterManager } = require('../services/cluster');
const { AccountMembership } = require('../models/billing');

const app = express();
app.use(express.json());

app.post('/api/clusters/:clusterId/scale', requireToken, async (req, res) => {
  const { clusterId } = req.params;
  const { nodeCount, targetBillingAccount } = req.body;

  const billingAccount = targetBillingAccount || req.user.primaryBillingAccount;

  // Validate that the authenticated caller has billing authority over this account
  const hasAuthority = await AccountMembership.findOne({
    where: { accountId: billingAccount, userId: req.user.id, canAuthorizeBilling: true }
  });

  if (!hasAuthority) {
    return res.status(403).json({ error: 'Access denied: You do not have billing authorization for this account' });
  }

  const result = await ClusterManager.provisionNodes(clusterId, nodeCount, billingAccount);
  res.json({ success: true, clusterId, nodesProvisioned: nodeCount, billedTo: billingAccount });
});

module.exports = app;
